PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE videos(
                vod_id TEXT PRIMARY KEY,
                title TEXT,
                pic_url TEXT,
                m3u8_url TEXT,
                vod_remarks TEXT,
                vod_pubdate TEXT,
                vod_area TEXT,
                vod_year TEXT,
                vod_content TEXT,
                vod_play_from TEXT,
                vod_play_url TEXT,
                type_name TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE actresses(
                cate_id TEXT PRIMARY KEY,
                name TEXT,
                avatar TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP, sex TEXT NOT NULL DEFAULT '', roster_id TEXT, claimed INTEGER);
CREATE TABLE tags(
                tag_name TEXT PRIMARY KEY,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE video_actress(
                vod_id TEXT,
                cate_id TEXT,
                PRIMARY KEY(vod_id, cate_id));
CREATE TABLE video_tag(
                vod_id TEXT,
                tag_name TEXT,
                PRIMARY KEY(vod_id, tag_name));
CREATE TABLE actor_ranking(
                vod_id TEXT,
                cate_id TEXT,
                PRIMARY KEY(vod_id, cate_id));
CREATE TABLE video_ranking(
                vod_id TEXT,
                cate_id TEXT,
                PRIMARY KEY(vod_id, cate_id));
CREATE TABLE video_category(
                vod_id TEXT PRIMARY KEY,
                main_category TEXT);
CREATE TABLE index_categories(
                category_type TEXT,
                category_name TEXT,
                video_count INTEGER DEFAULT 0,
                cover_image TEXT,
                output_dir TEXT,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                PRIMARY KEY(category_type, category_name));
CREATE TABLE video_play_urls (vod_id TEXT NOT NULL, play_url TEXT NOT NULL, play_from TEXT NOT NULL DEFAULT '', PRIMARY KEY (vod_id, play_url));
CREATE INDEX idx_va_c ON video_actress(cate_id);
CREATE INDEX idx_va_v ON video_actress(vod_id);
CREATE INDEX idx_vt_t ON video_tag(tag_name);
CREATE INDEX idx_vt_v ON video_tag(vod_id);
CREATE INDEX idx_ic_type ON index_categories(category_type);
CREATE INDEX idx_vc_main ON video_category(main_category);
COMMIT;
